import * as T from 'three';
import {box,cylinder,person,sign} from './models.js';
import {WATER_DOCK,WATER_VICTIM,WATER_HANDOVER} from './water-rescue.js';
export function rescueBoat(parent,crew=false){const g=new T.Group();parent.add(g);box(g,1.7,.16,3.8,'#444b4b',0,.18,0);for(const x of[-.92,.92]){const tube=cylinder(g,.3,.3,3.7,'#d34432',x,.4,0,10);tube.rotation.x=Math.PI/2;}const bow=cylinder(g,.3,.3,1.85,'#d34432',0,.4,1.75,10);bow.rotation.z=Math.PI/2;box(g,.7,.55,.4,'#29353a',0,.55,-1.9);box(g,1.5,.15,.38,'#586366',0,.45,-.7);if(crew)for(const x of[-.48,.48]){const p=person(g,x,-.55,'#202c35');p.scale.setScalar(.8);box(p,.57,.46,.36,'#f39c32',0,1.12,0);cylinder(p,.13,.13,.62,'#b6c6c9',0,1.08,-.29,8);}return g;}
export function installDiveKit(e){const boat=rescueBoat(e.model);boat.position.set(0,2.95,-.4);e.model.userData.carriedBoat=boat;for(const side of[-1,1]){const label=sign(e.model,'PLONGEURS',2.3,.35,side*1.09,1.85,-.6,'#bd292b','#ffffff');label.rotation.y=side*Math.PI/2;}}
export function updateWaterVisual(c,boat,victim,engine){const r=c.nautical;const active=!!r.unitId&&!r.done;boat.visible=active&&r.phase>0;if(engine)engine.model.userData.carriedBoat.visible=!active;const t=r.progress,a=r.dock||WATER_DOCK,b=r.victim||WATER_VICTIM;let pos=a;if(r.phase===1)pos=a.map((v,i)=>v+(b[i]-v)*t);else if(r.phase===2)pos=b;else if(r.phase===3)pos=b.map((v,i)=>v+(a[i]-v)*t);boat.position.set(pos[0],.25,pos[1]);boat.rotation.y=Math.atan2((r.phase>=3?a[0]-b[0]:b[0]-a[0]),(r.phase>=3?a[1]-b[1]:b[1]-a[1]));if(victim){victim.visible=!c.patients[0].evacuated;const carried=r.phase>=3&&!r.done,p=r.done?(r.handover||WATER_HANDOVER):carried?pos:b;victim.position.set(p[0],r.done?.6:carried?.9:.15,p[1]);}}
